INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-creacion-linguistica-con-globos', 'La Creación Lingüística con Globos', 'Dinámica de agilidad verbal y coordinación inflable donde los scouts inventan términos originales sin dejar caer el globo.', '<h2>📜 Descripción de La Creación Lingüística con Globos</h2>
<p><b>La Creación Lingüística con Globos</b> es una dinámica scout de rapidez mental, vocabulario inventivo y destreza física. En esta prueba cooperativa, cada patrulla se organiza en un pequeño círculo manteniendo un globo inflado en el aire mediante suaves toques de mano, cabeza o rodilla. Cada vez que un scout golpea el globo hacia un compañero, debe pronunciar en voz alta una palabra totalmente inventada (ej. <i>''Zulipampa''</i>, <i>''Cromaflor''</i> o <i>''Kinesaurio''</i>) junto con su significado improvisado en una sola frase antes de que el globo toque el suelo.</p>
<p>Esta actividad ejercita la soltura léxica, el pensamiento divergente y la agilidad muscular en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega La Creación Lingüística con Globos?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y alegría, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación del Círculo:</b> Las patrullas forman círculos de 4 a 6 participantes sosteniendo un globo inflado.</li>
  <li><b>Saque de Neologismos:</b> El primer jugador lanza el globo hacia arriba pronunciando su primera palabra inventada.</li>
  <li><b>Mantención y Significado:</b> El scout que recibe debe tocar el globo hacia otro par declarando el significado de la palabra anterior o creando una nueva.</li>
  <li><b>Prohibición de Repetición:</b> Queda prohibido repetir palabras de diccionarios reales o términos ya dichos en la ronda.</li>
  <li><b>Conteo de Toques:</b> La patrulla suma 1 punto por cada pase con palabra inventada exitosa sostenida en el aire.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Creación Lingüística con Globos</h2>
<p>La actividad valora la creatividad léxica y la destreza en el Tally:</p>
<ul>
  <li><b>Mayor Originalidad Lingüística:</b> Otorgar 5 puntos al equipo con las creaciones de palabras más ingeniosas y divertidas.</li>
  <li><b>Récord de Pases Continuos:</b> Otorgar 3 puntos a la patrulla que mantenga el globo en el aire durante más tiempo.</li>
  <li><b>Trabajo Cooperativo:</b> Otorgar 3 puntos a la unidad que integre equitativamente los toques entre todos sus miembros.</li>
</ul>', '/uploads/la-creacion-linguistica-con-globos.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Globos"], "objetivos": ["Estimular la creatividad", "Estimular la agilidad mental", "Fomentar la comunicación e interpretación", "Trabajo en equipo"], "justificacion_areas": "La Creación Lingüística con Globos potencia la creatividad al desafiar el pensamiento lateral e incentivar la invención de neologismos y construcciones idiomáticas sin juzgamiento. Desarrolla la sociabilidad al afianzar el soporte mutuo, el ritmo colectivo y la risa compartida desde Manada hasta Clan.", "variaciones": "<b>Diccionario Scout Neológico:</b> Registrar en un cuaderno de patrulla las 10 mejores palabras inventadas para el Tally.<br><b>Globos Gigantes en Parejas:</b> Realizar los toques sujetados de las manos en duplas.<br><b>Edición Definiciones Absurdas:</b> Un scout dice la palabra inventada y su receptor define el uso scout de dicha palabra.", "recomendaciones": "Tener globos de repuesto por si alguno se revienta. Fomentar un ambiente relajado donde no exista el miedo al error de pronunciación.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando la trayectoria del globo para reaccionar a tiempo con la palabra."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Inventando palabras graciosas mientras se mantiene el globo flotando."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando las normas de no repetir palabras y coordinar los toques."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Apoyando al compañero cuando se le dificulte encontrar un neologismo."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Aportando creatividad lingüística y riqueza de vocabulario en la dinámica."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Conectando significados ingeniosos de forma rápida según el bote del globo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el ambiente de aliento y risa sana en la patrulla."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo la desinhibición y el disfrute compartido sin discriminación."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "unidad": "Tropa", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Organizando estrategias de pases para maximizar los neologismos."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Asociando ideas y términos abstractos en milisegundos."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando la cooperación activa y la escucha atenta de las definiciones."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fortaleciendo la fraternidad e inclusión entre todos los miembros."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Promoviendo el pensamiento divergente y la soltura de expresión en la Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Liderando dinámicas de desinhibición y cohesión responsable."}, {"id": "ef75fbed-4a6d-49ea-bfab-f2952415e1a0", "area": "Creatividad", "unidad": "Clan", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Ejercitando agilidad mental superior e innovación expresiva en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Desarrollando la camaradería, el servicio alegre y la hermandad scout."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

